-- CYBERTUBE: SEED MITRE ATT&CK INCIDENT RESPONSE ZERO TO ADVANCED COMPLETE COURSE
-- =============================================================================

-- 1. Course
INSERT INTO public.courses (
  id, slug, title, short_description, description, difficulty, estimated_duration, total_duration_minutes,
  thumbnail_url, instructor_name, instructor_title, instructor_org, status, tags, prerequisites,
  learning_objectives, track, domains, featured
) VALUES (
  'dc000000-0000-4000-8000-000000000001', 'mitre-attack-incident-response-zero-to-advanced', 'MITRE ATT&CK for Incident Response: Zero to Advanced', 'A comprehensive 30-module, video-guided defensive incident response curriculum aligned with MITRE ATT&CK Enterprise v20.1 and NIST SP 800-61r3, 150 lessons, hands-on SOC cases, DFIR investigations, and a full capstone portfolio.', 'A comprehensive, hands-on 30-module defensive cybersecurity curriculum designed for aspiring and practicing SOC L1/L2 analysts, incident responders, and DFIR professionals. Master enterprise incident response aligned with MITRE ATT&CK Enterprise v20.1 and NIST SP 800-61r3: SOC triage, evidence preservation, chain of custody, Windows/Linux host forensics, network PCAP analysis, credential access, persistence mechanisms, defense impairment, lateral movement, ransomware containment, timeline reconstruction, memory analysis, detection engineering, threat hunting, ATT&CK Navigator mapping, and post-incident recovery, culminating in a full ATT&CK-informed incident investigation capstone portfolio.',
  'intermediate', '30 modules (234 hours)', 5250,
  'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=800&q=80',
  'CyberTube IR Curators & MITRE Open Community', 'Incident Response & SOC Detection Engineers',
  'MITRE ATT&CK, CISA, TryHackMe & Open DFIR Community', 'published',
  ARRAY['mitre-attack', 'incident-response', 'dfir', 'soc-analyst', 'threat-hunting', 'detection-engineering', 'nist-800-61r3', 'forensics', 'windows-security', 'ransomware']::TEXT[], ARRAY['Basic understanding of operating system internals (Windows and Linux logs)', 'Familiarity with foundational networking protocols (TCP/IP, DNS, HTTP, TLS)', 'Commitment to ethical defensive investigation within authorized boundaries']::TEXT[], ARRAY['Differentiate security telemetry, events, alerts, and validated incidents using NIST SP 800-61r3', 'Navigate, query, and map adversary behaviors to the MITRE ATT&CK Enterprise v20.1 matrix', 'Distinguish between ATT&CK Tactics (why), Techniques (how), Sub-techniques, and empirical Procedures', 'Apply the ATT&CK v20.1 separation between Stealth (TA0045) and Defense Impairment (TA0046)', 'Preserve digital evidence following the RFC 3227 Order of Volatility and cryptographic chain of custody', 'Investigate Windows and Linux endpoint telemetry, including Sysmon, Event ID 4624/4625, and /var/log/auth.log', 'Triage network PCAP captures, DNS tunneling cadences, TLS handshakes, and phishing email headers', 'Detect credential spraying, Kerberoasting, LSASS dumping, persistence Run keys, and PsExec lateral movement', 'Execute Volatility 3 memory analysis to identify injected shellcode (malfind) and hidden processes (psscan)', 'Deliver an executive-level incident investigation report, ATT&CK Navigator layer, and remediation roadmap']::TEXT[], 'cybersecurity', ARRAY['soc-blue-team', 'dfir', 'fundamentals']::TEXT[], true
)
