INSERT INTO public.course_modules (id, course_id, title, description, order_index) VALUES
  ('dc000000-0000-4000-8000-000000000101', 'dc000000-0000-4000-8000-000000000001', 'Module 01: SOC and Incident Response Orientation', 'Foundations stage (Zero difficulty). Estimated effort: 5 hours. Focus: Incident detection vs investigation vs response', 1),
  ('dc000000-0000-4000-8000-000000000102', 'dc000000-0000-4000-8000-000000000001', 'Module 02: Incident Response Frameworks and NIST SP 800-61r3', 'Foundations stage (Zero difficulty). Estimated effort: 6 hours. Focus: Preparation; Detect; Respond; Recover; continuous improvement', 2),
  ('dc000000-0000-4000-8000-000000000103', 'dc000000-0000-4000-8000-000000000001', 'Module 03: MITRE ATT&CK: What It Is and Why Responders Use It', 'Foundations stage (Zero difficulty). Estimated effort: 5 hours. Focus: ATT&CK Enterprise, adversary behavior and evidence', 3),
  ('dc000000-0000-4000-8000-000000000104', 'dc000000-0000-4000-8000-000000000001', 'Module 04: Tactics, Techniques, Sub-techniques and Procedures', 'Foundations stage (Beginner difficulty). Estimated effort: 6 hours. Focus: ATT&CK object vocabulary and confidence', 4),
  ('dc000000-0000-4000-8000-000000000105', 'dc000000-0000-4000-8000-000000000001', 'Module 05: ATT&CK Enterprise v20.1 Navigation and Version Control', 'Foundations stage (Beginner difficulty). Estimated effort: 5 hours. Focus: Enterprise v20.1 and tactic updates', 5),
  ('dc000000-0000-4000-8000-000000000106', 'dc000000-0000-4000-8000-000000000001', 'Module 06: Turn Incident Narratives into ATT&CK Mappings', 'Foundations stage (Beginner difficulty). Estimated effort: 7 hours. Focus: Evidentiary technique mapping', 6),
  ('dc000000-0000-4000-8000-000000000107', 'dc000000-0000-4000-8000-000000000001', 'Module 07: IR Preparedness: Playbooks, Contacts and Evidence Readiness', 'Operational IR stage (Beginner difficulty). Estimated effort: 6 hours. Focus: Preparedness, runbooks and responsibilities', 7),
  ('dc000000-0000-4000-8000-000000000108', 'dc000000-0000-4000-8000-000000000001', 'Module 08: SOC Alert Triage, Severity and Escalation', 'Operational IR stage (Beginner difficulty). Estimated effort: 6 hours. Focus: SOC incident workflow and ATT&CK triage', 8),
  ('dc000000-0000-4000-8000-000000000109', 'dc000000-0000-4000-8000-000000000001', 'Module 09: Digital Evidence, Preservation and Chain of Custody', 'Operational IR stage (Beginner difficulty). Estimated effort: 7 hours. Focus: Evidence provenance and admissibility awareness', 9),
  ('dc000000-0000-4000-8000-000000000110', 'dc000000-0000-4000-8000-000000000001', 'Module 10: Windows Authentication and Identity Investigation', 'Endpoint IR stage (Intermediate difficulty). Estimated effort: 7 hours. Focus: Authentication patterns and credential access evidence', 10),
  ('dc000000-0000-4000-8000-000000000111', 'dc000000-0000-4000-8000-000000000001', 'Module 11: Windows Process, PowerShell and Sysmon Telemetry', 'Endpoint IR stage (Intermediate difficulty). Estimated effort: 8 hours. Focus: Execution and persistence detection evidence', 11),
  ('dc000000-0000-4000-8000-000000000112', 'dc000000-0000-4000-8000-000000000001', 'Module 12: Linux and SSH Incident Investigation', 'Endpoint IR stage (Intermediate difficulty). Estimated effort: 7 hours. Focus: Linux auth, processes and services', 12),
  ('dc000000-0000-4000-8000-000000000113', 'dc000000-0000-4000-8000-000000000001', 'Module 13: Network Forensics: DNS, HTTP, TLS and PCAP', 'Network IR stage (Intermediate difficulty). Estimated effort: 9 hours. Focus: Network observations, beaconing and exfiltration clues', 13),
  ('dc000000-0000-4000-8000-000000000114', 'dc000000-0000-4000-8000-000000000001', 'Module 14: Phishing, Initial Access and User Execution', 'Attack Behaviors stage (Intermediate difficulty). Estimated effort: 8 hours. Focus: Phishing, suspicious attachments and initial access', 14),
  ('dc000000-0000-4000-8000-000000000115', 'dc000000-0000-4000-8000-000000000001', 'Module 15: Credential Access and Compromised Identity', 'Attack Behaviors stage (Intermediate difficulty). Estimated effort: 8 hours. Focus: Credentials, anomalous sign-ins and privilege use', 15),
  ('dc000000-0000-4000-8000-000000000116', 'dc000000-0000-4000-8000-000000000001', 'Module 16: Persistence and Privilege Escalation', 'Attack Behaviors stage (Intermediate difficulty). Estimated effort: 8 hours. Focus: Persistence mechanisms and privilege changes', 16),
  ('dc000000-0000-4000-8000-000000000117', 'dc000000-0000-4000-8000-000000000001', 'Module 17: Stealth and Defense Impairment (Current ATT&CK)', 'Attack Behaviors stage (Intermediate difficulty). Estimated effort: 7 hours. Focus: Stealth; Defense Impairment; monitoring blind spots', 17),
  ('dc000000-0000-4000-8000-000000000118', 'dc000000-0000-4000-8000-000000000001', 'Module 18: Discovery and Lateral Movement Investigation', 'Attack Behaviors stage (Advanced difficulty). Estimated effort: 8 hours. Focus: Discovery, remote services and account scope', 18),
