  ('dc000000-0000-4000-8000-000000000121', 'dc000000-0000-4000-8000-000000000001', 'Module 21: Forensic Acquisition and Memory Fundamentals', 'Digital Forensics stage (Advanced difficulty). Estimated effort: 9 hours. Focus: Memory and disk evidence principles', 21),
  ('dc000000-0000-4000-8000-000000000122', 'dc000000-0000-4000-8000-000000000001', 'Module 22: Timeline Reconstruction and Case Management', 'Digital Forensics stage (Advanced difficulty). Estimated effort: 8 hours. Focus: Unified timelines, investigation case notes', 22),
  ('dc000000-0000-4000-8000-000000000123', 'dc000000-0000-4000-8000-000000000001', 'Module 23: Malware and Suspicious Document Triage', 'Digital Forensics stage (Advanced difficulty). Estimated effort: 8 hours. Focus: Safe triage of suspicious files', 23),
